1	package main
2	
3	import (
4		"encoding/json"
5		"strings"
6		"testing"
7	
8		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
9	)
10	
11	// These tests pin conflict adjudication at the command boundary after a
12	// save: the config is parsed through the public entry point, written with
13	// the standard library's encoding/json (the supported save path) and read
14	// back, and the real `resolve` command is then run offline against both the
15	// original and the saved config files. Exit status, stdout and stderr must
16	// match byte for byte in their observable JSON content, so a save cannot
17	// turn a conflict into a success, change the error code or move candidates.
18	
19	// saveConfigJSON parses a config document through the public reader and
20	// writes it back with encoding/json, failing the test if the saved document
21	// would not re-read as a legal config.
22	func saveConfigJSON(t *testing.T, src string) string {
23		t.Helper()
24		cfg, f := contractsentinel.ParseConfig([]byte(src))
25		if f != nil {
26			t.Fatalf("parse original config: %v", f)
27		}
28		out, err := json.Marshal(cfg)
29		if err != nil {
30			t.Fatalf("marshal config: %v", err)
31		}
32		if _, f := contractsentinel.ParseConfig(out); f != nil {
33			t.Fatalf("saved config rejected on re-read: %v\n%s", f, out)
34		}
35		return string(out)
36	}
37	
38	// assertCLISameResult runs resolve against the original and the saved
39	// config and requires identical observable behavior: exit status, the full
40	// stdout (routeId/upstreamURL on success) and the full stderr JSON
41	// (code/reason/candidates on failure).
42	func assertCLISameResult(t *testing.T, original, saved, request string) resolveResult {
43		t.Helper()
44		before := runResolveCLI(t, original, request)
45		after := runResolveCLI(t, saved, request)
46		if before.exitCode != after.exitCode {
47			t.Fatalf("exit status changed across save for %s: %d vs %d\n before stderr: %s\n after stderr:  %s",
48				request, before.exitCode, after.exitCode, before.stderr, after.stderr)
49		}
50		if string(before.stdout) != string(after.stdout) {
51			t.Fatalf("stdout changed across save for %s:\n before: %s\n after:  %s",
52				request, before.stdout, after.stdout)
53		}
54		if string(before.stderr) != string(after.stderr) {
55			t.Fatalf("stderr changed across save for %s:\n before: %s\n after:  %s",
56				request, before.stderr, after.stderr)
57		}
58		return after
59	}
60	
61	// cliFailure is the stderr failure contract decoded for explicit assertions.
62	type cliFailure struct {
63		Code       string   `json:"code"`
64		Reason     string   `json:"reason"`
65		Candidates []string `json:"candidates"`
66	}
67	
68	func decodeCLIFailure(t *testing.T, res resolveResult) cliFailure {
69		t.Helper()
70		if res.exitCode == 0 {
71			t.Fatalf("expected non-zero exit, got success: %s", res.stdout)
72		}
73		if len(res.stdout) != 0 {
74			t.Fatalf("stdout = %q, want empty on failure", res.stdout)
75		}
76		var f cliFailure
77		decodeOneJSON(t, res.stderr, "stderr", &f)
78		return f
79	}
80	
81	func TestResolveCLISaveKeepsLongestWildcardWin(t *testing.T) {
82		// Two concrete GET routes share /a; a wildcard route owns the longer
83		// /a/b. Before and after saving, a request inside /a/b selects the
84		// wildcard with the stripped path and the raw query intact, while a
85		// request under /a alone stays a conflict.
86		config := `{
87		  "routes": [
88		    {"id": "short-one", "methods": ["GET"], "pathPrefix": "/a", "upstream": "http://one.internal/s1"},
89		    {"id": "short-two", "methods": ["GET"], "pathPrefix": "/a", "upstream": "http://two.internal/s2"},
90		    {"id": "long-wild", "methods": ["*"], "pathPrefix": "/a/b", "upstream": "http://wild.internal/base"}
91		  ]
92		}`
93		saved := saveConfigJSON(t, config)
94	
95		for _, req := range []string{
96			`{"method":"GET","target":"/a/b/c/items?dup=1&dup=2&empty=&raw=%2f%41&%26=x"}`,
97			`{"method":"GET","target":"/a/b"}`,
98			`{"method":"POST","target":"/a/b/c"}`,
99		} {
100			res := assertCLISameResult(t, config, saved, req)
101			if res.exitCode != 0 || len(res.stderr) != 0 {
102				t.Fatalf("request %s: expected success, got exit %d stderr %s", req, res.exitCode, res.stderr)
103			}
104			var success struct {
105				RouteID     string `json:"routeId"`
106				UpstreamURL string `json:"upstreamURL"`
107			}
108			decodeOneJSON(t, res.stdout, "stdout", &success)
109			if success.RouteID != "long-wild" {
110				t.Fatalf("request %s: routeId = %q, want long-wild", req, success.RouteID)
111			}
112		}
113	
114		// Explicitly pin the full upstream for the deep path: remainder joined
115		// after the stripped prefix, raw query with duplicates, empty value and
116		// percent escapes kept byte for byte.
117		res := runResolveCLI(t, saved,
118			`{"method":"GET","target":"/a/b/c/items?dup=1&dup=2&empty=&raw=%2f%41&%26=x"}`)
119		if res.exitCode != 0 {
120			t.Fatalf("saved config: exit %d, stderr %s", res.exitCode, res.stderr)
121		}
122		var success struct {
123			RouteID     string `json:"routeId"`
124			UpstreamURL string `json:"upstreamURL"`
125		}
126		decodeOneJSON(t, res.stdout, "stdout", &success)
127		wantURL := "http://wild.internal/base/c/items?dup=1&dup=2&empty=&raw=%2f%41&%26=x"
128		if success.RouteID != "long-wild" || success.UpstreamURL != wantURL {
129			t.Fatalf("saved config: got %+v, want long-wild / %q", success, wantURL)
130		}
131	
132		// The short-prefix request stays a request-stage conflict after saving:
133		// same code, non-empty reason and exactly the two short routes.
134		res = assertCLISameResult(t, config, saved, `{"method":"GET","target":"/a/only?z=1"}`)
135		f := decodeCLIFailure(t, res)
136		if f.Code != "route_conflict" {
137			t.Fatalf("code = %q, want route_conflict", f.Code)
138		}
139		if f.Reason == "" {
140			t.Fatal("route_conflict must carry a reason")
141		}
142		if got := strings.Join(f.Candidates, ","); got != "short-one,short-two" {
143			t.Fatalf("candidates = %v, want [short-one short-two]", f.Candidates)
144		}
145	}
146	
147	func TestResolveCLISaveKeepsConflictCandidatesExact(t *testing.T) {
148		// At /a/b: two concrete GET routes (declared zeta before alpha, not in
149		// lexicographic order), a same-prefix wildcard and a shorter concrete
150		// route. The saved config must keep the GET conflict with only the two
151		// concrete routes sorted; POST must still win the wildcard.
152		config := `{
153		  "routes": [
154		    {"id": "z-short",   "methods": ["GET"], "pathPrefix": "/a",   "upstream": "http://short.internal"},
155		    {"id": "wild-long", "methods": ["*"],   "pathPrefix": "/a/b", "upstream": "http://wild.internal/w"},
156		    {"id": "zeta",      "methods": ["GET"], "pathPrefix": "/a/b", "upstream": "http://z.internal"},
157		    {"id": "alpha",     "methods": ["GET"], "pathPrefix": "/a/b", "upstream": "http://a.internal"}
158		  ]
