80		// rename-into-an-existing-name followed by set, and untouched fragments
81		// must resolve identically before and after the save.
82		target := "/c?keep=1&x=7&b=2&a+b=q&%25=raw&dup=1&dup=2&flag&keep=2&e="
83		after, saved := roundTripResolve(t, cfg, "GET", target)
84		if after.RouteID != "rich" {
85			t.Fatalf("routeId = %q, want rich", after.RouteID)
86		}
87		// Sanity-check the rewritten query itself: x renames onto the existing b
88		// and set merges both into one b=9 at x's position; dup collapses to an
89		// empty value; flag is gone; the rest keeps order and bytes.
90		wantQuery := "?keep=1&b=9&%E4%B8%AD%20%E6%96%87%2B=q&%25=p%20c%2B%2525&dup=&keep=2&e="
