// save-roundtrip 示例：离线读取路由配置 -> 保存为 JSON -> 重新读取 ->
// 用保存前后的两份配置解析同一个请求。全程只使用 contractsentinel 的
// 公开入口（ParseConfig / ParseRequest / Resolve）与标准库 encoding/json，
// 不建立任何网络连接。
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"

	"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
)

func main() {
	// 1) 读入配置文件。ParseConfig 是完整校验入口：JSON 语法、结构、
	//    字段类型、queryTransforms 规则与字段内容（前缀、上游地址等）
	//    全部通过后才返回 *Config；失败时返回 nil 与 *Failure，读取
	//    失败的配置不会被继续使用。
	raw, err := os.ReadFile("routes.json")
	must(err)
	cfg, ok := load(raw, "routes.json")
	if !ok {
		os.Exit(1)
	}

	// 2) 把读入的配置保存为 JSON（缩进可任意；这里用两空格缩进）。
	//    规则的名称、值与目标名按字面值写出，不做查询串百分号编码。
	saved, err := marshalIndented(cfg)
	must(err)
	must(os.WriteFile("routes.saved.json", saved, 0o644))
	fmt.Println("=== saved JSON (routes.saved.json) ===")
	fmt.Println(string(saved))

	// 3) 保存后的文件重新走同一个完整校验入口读取。
	reloaded, ok := load(saved, "routes.saved.json")
	if !ok {
		os.Exit(1)
	}

	// 4) 解析同一个请求，并分别用保存前、保存后的配置解析；routeId 与
	//    upstreamURL 必须完全一致。请求含重复参数、空值与原始百分号编码。
	request := []byte(`{"method":"get","target":"/api/orders/7?old=1&old=2&flag&keep=%2f%41&e=&old=3&z"}`)
	req, f := contractsentinel.ParseRequest(request)
	if f != nil {
		printFailure(f)
		os.Exit(1)
	}
	before, f := contractsentinel.Resolve(cfg, req)
	if f != nil {
		printFailure(f)
		os.Exit(1)
	}
	after, f := contractsentinel.Resolve(reloaded, req)
	if f != nil {
		printFailure(f)
		os.Exit(1)
	}
	fmt.Println("=== resolve before save ===")
	printResolution(before)
	fmt.Println("=== resolve after save/reload ===")
	printResolution(after)

	// 5) 容易误解的保存结果一：省略 queryTransforms 与显式 [] 都保存为
	//    省略该字段，原查询串此后不被改写。
	ruleless := []byte(`{"routes":[
	  {"id":"absent","methods":["*"],"pathPrefix":"/a","upstream":"http://h"},
	  {"id":"empty","methods":["*"],"pathPrefix":"/b","upstream":"http://h","queryTransforms":[]}
	]}`)
	rl, ok := load(ruleless, "ruleless")
	if !ok {
		os.Exit(1)
	}
	out, err := marshalIndented(rl)
	must(err)
	fmt.Println("=== ruleless routes saved (no queryTransforms key, no null) ===")
	fmt.Println(string(out))

	// 6) 容易误解的保存结果二：空路由配置保存为 routes 空数组而不是 null，
	//    再次读取仍合法；合法请求对其解析得到 route_not_found。
	empty, ok := load([]byte(`{}`), "empty")
	if !ok {
		os.Exit(1)
	}
	out, err = json.Marshal(empty)
	must(err)
	fmt.Printf("=== empty routes saved: %s ===\n", string(out))
	reloadedEmpty, ok := load(out, "saved-empty")
	if !ok {
		os.Exit(1)
	}
	_, f = contractsentinel.Resolve(reloadedEmpty, req)
	fmt.Println("=== resolve against saved empty routes ===")
	printFailure(f)

	// 7) 读取失败的配置：ParseConfig 返回 nil，调用方只能展示 code 与
	//    reason 并停止使用它（remove 不允许带 value）。
	bad := []byte(`{"routes":[{"id":"r","methods":["*"],"pathPrefix":"/","upstream":"http://h",
	  "queryTransforms":[{"op":"remove","name":"x","value":"1"}]}]}`)
	fmt.Println("=== reading an invalid config ===")
	if _, ok := load(bad, "bad"); !ok {
		fmt.Println("(no config returned; it is never used)")
	}
}

// load 通过完整校验入口读取配置；失败时打印 code 与 reason 并返回
// ok=false，调用方不得使用那份配置。
func load(data []byte, label string) (*contractsentinel.Config, bool) {
	cfg, f := contractsentinel.ParseConfig(data)
	if f != nil {
		fmt.Fprintf(os.Stderr, "cannot use %s:\n", label)
		printFailure(f)
		return nil, false
	}
	return cfg, true
}

func printFailure(f *contractsentinel.Failure) {
	fmt.Printf("code:   %s\nreason: %s\n", f.Code, f.Reason)
}

func printResolution(r *contractsentinel.Resolution) {
	fmt.Printf("routeId:     %s\n", r.RouteID)
	fmt.Printf("upstreamURL: %s\n", r.UpstreamURL)
}

// marshalIndented 保存配置，同时关闭 HTML 转义，让字符串中的 & 等字符
// 原样出现（配置内容本身按字面值保存）。
func marshalIndented(cfg *contractsentinel.Config) ([]byte, error) {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(cfg); err != nil {
		return nil, err
	}
	return bytes.TrimRight(buf.Bytes(), "\n"), nil
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

